package com.intermarche.backoffice.engine.fieldops;
import com.intermarche.backoffice.domain.policy.OperationalPolicyVersion;import com.intermarche.backoffice.domain.store.Store;import com.intermarche.backoffice.engine.policy.OperationalPolicySchemas;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import java.util.*;
@ApplicationScoped public class OperationalPolicyVersions {
 @Inject FieldOperationsService field;@Inject ObjectMapper mapper;
 public OperationalPolicyVersion record(Store store,String kind,Object values,String reason){ObjectNode specification=mapper.valueToTree(values);specification.remove(List.of("revision","canManage"));specification.put("type",kind);String key=OperationalPolicySchemas.scope(specification);var latest=OperationalPolicyVersion.<OperationalPolicyVersion>find("store=?1 and scopeKey=?2 order by revisionNumber desc",store,key).firstResult();for(var old:OperationalPolicyVersion.<OperationalPolicyVersion>list("store=?1 and scopeKey=?2 and active=true",store,key))old.active=false;var version=new OperationalPolicyVersion();version.store=store;version.kind=kind;version.scopeKey=key;version.revisionNumber=latest==null?1:latest.revisionNumber+1;version.activatedBy=field.actor();version.specification=field.encode(specification);version.reason=reason;version.persistAndFlush();return version;}
 public static JsonNode active(Store store,String kind){var row=OperationalPolicyVersion.<OperationalPolicyVersion>find("store=?1 and scopeKey=?2 and active=true",store,kind).firstResult();if(row==null)return OperationalPolicySchemas.defaults(kind);try{return new ObjectMapper().readTree(row.specification);}catch(Exception e){throw new IllegalStateException("Politique active illisible",e);}}
}
